// Builds an LS shadowing video from sentences cut out of the LS's own recordings.
// Intro (what shadowing is, how to do it, tips, worked examples), then for each sentence:
// listen and read → your turn with the text (pause) → listen again, no text → your turn (pause).
// Usage: node tools/shadowing-video/build.js tools/shadowing-video/<ls>.json [workdir]
// Needs ffmpeg and Playwright (Chromium). Nothing is generated by a paid service.
const fs = require('fs');
const path = require('path');
const os = require('os');
const { execFileSync } = require('child_process');
const { chromium } = require('playwright');

const ROOT = path.resolve(__dirname, '../..');
const spec = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const work = process.argv[3] || fs.mkdtempSync(path.join(os.tmpdir(), 'shadow-'));
fs.mkdirSync(work, { recursive: true });
const T = spec.theme;
const W = 1280, H = 720, FPS = 30;
const LEAD = 0.5, TAIL = 0.5;                      // silence around each playback
const BAR = { x: 290, y: 612, w: 700, h: 14 };      // timer bar during the pauses

const ff = (args) => execFileSync('ffmpeg', ['-nostdin', '-v', 'error', '-y', ...args]);
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const pretty = (s) => esc(s).replace(/'/g, '’');

const ICON = {
  ear: '<path d="M22 84V70a46 46 0 0 1 92 0v14" fill="none" stroke="currentColor" stroke-width="10" stroke-linecap="round"/><rect x="16" y="76" width="28" height="44" rx="10" fill="currentColor"/><rect x="92" y="76" width="28" height="44" rx="10" fill="currentColor"/>',
  mic: '<rect x="50" y="18" width="36" height="66" rx="18" fill="currentColor"/><path d="M34 66c0 20 15 34 34 34s34-14 34-34M68 100v22M50 124h36" fill="none" stroke="currentColor" stroke-width="9" stroke-linecap="round"/>',
};

function page(body) {
  return `<!doctype html><html><head><meta charset="utf-8"><style>
  *{box-sizing:border-box;margin:0}
  body{width:${W}px;height:${H}px;font-family:Inter,sans-serif;color:${T.ink};overflow:hidden;
    background:radial-gradient(circle at 88% 12%,${T.soft} 0,transparent 32%),linear-gradient(135deg,${T.bg1},${T.bg2});position:relative}
  .top{position:absolute;top:36px;left:56px;right:56px;display:flex;justify-content:space-between;align-items:center}
  .brand{display:flex;align-items:center;gap:14px;font-weight:700;font-size:21px;color:${T.title}}
  .logo{width:36px;height:36px;border-radius:9px;background:${T.accent};display:grid;place-items:center}
  .site{font-size:16px;font-weight:600;color:${T.muted}}
  .steps{position:absolute;top:104px;left:0;right:0;display:flex;justify-content:center;gap:10px}
  .st{padding:7px 16px;border-radius:999px;font-size:16px;font-weight:600;color:${T.muted};background:#fff;border:1.5px solid ${T.soft}}
  .st.on{background:${T.accent};border-color:${T.accent};color:#fff}
  .card{position:absolute;left:110px;right:110px;top:164px;height:400px;background:#fff;border-radius:28px;
    box-shadow:0 18px 50px rgba(30,50,90,.10);border:1px solid ${T.soft};display:flex;flex-direction:column;align-items:center;justify-content:center;padding:30px 60px;text-align:center}
  .who{font-size:18px;font-weight:700;color:${T.accent};letter-spacing:.02em;margin-bottom:18px;text-transform:uppercase}
  .say{font-weight:800;line-height:1.18;letter-spacing:-.01em}
  .dim{color:#9aa6b8}
  .icon{width:132px;height:132px;color:${T.accent};margin-bottom:20px}
  .big{font-size:44px;font-weight:800;color:${T.title}}
  .hint{font-size:22px;font-weight:500;color:${T.muted};margin-top:12px}
  .track{position:absolute;left:${BAR.x}px;top:${BAR.y}px;width:${BAR.w}px;height:${BAR.h}px;border-radius:3px;background:${T.soft}}
  .count{position:absolute;bottom:34px;left:0;right:0;text-align:center;font-size:17px;font-weight:600;color:${T.muted}}
  .lead{font-size:30px;font-weight:500;line-height:1.45;max-width:900px}
  .lead b,ul b{color:${T.accent}}
  ul{font-size:27px;font-weight:500;line-height:1.75;text-align:left;padding-left:30px}
  .strong{color:${T.accent};text-decoration:underline;text-decoration-thickness:5px;text-underline-offset:9px}
  .link{color:${T.accent};font-weight:900}
  .tone{color:${T.accent};font-weight:800;margin-left:.25em;font-family:'Noto Sans Symbols 2','DejaVu Sans',Inter,sans-serif}
  .legend{display:flex;gap:26px;justify-content:center;margin-top:22px;padding-top:18px;border-top:2px solid ${T.soft};font-size:23px;font-weight:600;color:${T.ink}}
  .legend span{white-space:nowrap}
  .join{color:${T.accent}}
  .turn{display:flex;align-items:center;gap:8px;background:${T.accent};color:#fff;padding:7px 18px 7px 12px;border-radius:999px;text-transform:none;letter-spacing:0}
  .turn svg{width:26px;height:26px;color:#fff}
  ol{font-size:27px;font-weight:600;line-height:1.75;text-align:left;color:${T.ink};padding-left:36px}
  ol b{color:${T.accent}}
  </style></head><body>
  <div class="top"><div class="brand"><span class="logo"><svg width="20" height="20" viewBox="0 0 20 20"><path d="M6 4l10 6-10 6z" fill="#fff"/></svg></span>Shadowing · ${esc(spec.ls)}</div>
  <div class="site">English Lab · ${esc(spec.course)}</div></div>${body}</body></html>`;
}

const STEPS = ['1 Listen and read', '2 Repeat', '3 Listen', '4 Repeat'];
const steps = (on) => `<div class="steps">${STEPS.map((s, i) => `<span class="st${i === on ? ' on' : ''}">${s}</span>`).join('')}</div>`;
const size = (t) => (t.length > 60 ? 46 : t.length > 40 ? 52 : 60);

// Marks (Roger, 31 Oct 2026): **stressed** syllables underlined, ‿ between linked words, ↗ ↘ the melody: ↗ before a comma and in yes/no questions, ↘ at the end and in wh- questions.
const marked = (t) => pretty(t).replace(/\*\*(.+?)\*\*/g, '<span class="strong">$1</span>').replace(/==(.+?)==/g, '<span class="join">$1</span>')
  .replace(/‿/g, '<span class="link">‿</span>').replace(/([,.?!:;])\s*([↗↘])/g, '$2$1')
  .replace(/\s*([↗↘])/g, '<span class="tone">$1</span>'); // arrow right after the word, before the comma or full stop (Roger)
const turnLabel = (txt, icon = ICON.mic) => `<div class="who turn"><svg viewBox="0 0 136 136">${icon}</svg>${txt}</div>`;
const clipLen = (it) => it.end - it.start;
const play = (it) => LEAD + clipLen(it) + TAIL;
const INTRO = [8, 11, 11], READY = 3, OUTRO = 4, GAP = 0.8;

function slides() {
  const n = spec.items.length, out = [], ex = spec.examples || [];
  out.push(['i0', page(`<div class="card" style="top:120px;height:470px">
    <div class="big" style="margin-bottom:24px">What is shadowing?</div>
    <div class="lead">You copy a speaker, like an echo: the <b>same words</b>, the <b>same speed</b>, the <b>same rhythm</b> and the <b>same melody</b>.</div>
    <div class="lead" style="margin-top:22px">It helps you speak more fluently and understand fast English.</div></div>
    <div class="count">${n} sentences</div>`)]);
  out.push(['i1', page(`<div class="card" style="top:120px;height:470px">
    <div class="big" style="margin-bottom:26px">How to do it</div>
    <ol><li><b>Listen</b> and read the sentence.</li><li><b>Your turn:</b> say it out loud, with the text.</li>
    <li><b>Listen again</b>, this time with no text.</li><li><b>Your turn again</b>, from memory.</li></ol>
    <div class="hint" style="margin-top:22px">A chime tells you it’s your turn. The video waits for you: the bar shows how long you have.</div></div>`)]);
  out.push(['i2', page(`<div class="card" style="top:105px;height:510px">
    <div class="big" style="margin-bottom:16px">Tips</div>
    <ul><li>Say it <b>out loud</b>, not in your head.</li><li>Copy the <b>music</b>: strong words are louder and longer.</li>
    <li><b>Join</b> the words like the speaker does.</li><li>Made a mistake? <b>Keep going.</b></li></ul>
    <div class="legend"><span><span class="strong">Strong</span> = louder, longer</span><span>a<span class="link">‿</span>b = join them</span><span><span class="tone" style="margin:0">↗</span> up · <span class="tone" style="margin:0">↘</span> down = the melody</span></div>
    <div class="hint" style="margin-top:12px"><span class="tone" style="margin:0">↗</span> before a comma, yes/no questions · <span class="tone" style="margin:0">↘</span> at the end, wh- questions</div></div>`)]);
  ex.forEach((it, i) => {
    const sz = size(it.text), head = `<div class="steps"><span class="st on">Example ${i + 1} of ${ex.length}</span></div>`;
    const tip = `<div class="hint" style="margin-top:26px">${esc(it.tip)}</div>`;
    out.push([`e${i}a`, page(head + `<div class="card">${turnLabel('Listen twice: ' + esc(it.speaker), ICON.ear)}<div class="say" style="font-size:${sz}px">${marked(it.marks)}</div>${tip}</div>`)]);
    out.push([`e${i}b`, page(head + `<div class="card">${turnLabel('Now you try!')}<div class="say" style="font-size:${sz}px">${marked(it.marks)}</div>${tip}</div><div class="track"></div>`)]);
  });
  out.push(['ready', page(`<div class="card"><div class="big">Ready? Let’s start!</div></div>`)]);
  spec.items.forEach((it, i) => {
    const sz = size(it.text), cnt = `<div class="count">Sentence ${i + 1} of ${n}</div>`;
    const say = `<div class="say" style="font-size:${sz}px">${it.marks ? marked(it.marks) : pretty(it.text)}</div>`;
    out.push([`s${i}a`, page(steps(0) + `<div class="card"><div class="who">${esc(it.speaker)}</div>${say}</div>` + cnt)]);
    out.push([`s${i}b`, page(steps(1) + `<div class="card">${turnLabel('Your turn: say it!')}${say}</div><div class="track"></div>` + cnt)]);
    out.push([`s${i}c`, page(steps(2) + `<div class="card"><svg class="icon" viewBox="0 0 136 136">${ICON.ear}</svg>
      <div class="big">Listen again</div><div class="hint">No text this time.</div></div>` + cnt)]);
    out.push([`s${i}d`, page(steps(3) + `<div class="card"><svg class="icon" viewBox="0 0 136 136">${ICON.mic}</svg>
      <div class="big">Your turn: say it again!</div><div class="hint">From memory, same speed and rhythm.</div></div><div class="track"></div>` + cnt)]);
  });
  out.push(['outro', page(`<div class="card"><div class="big">Well done!</div><div class="hint">Play it again tomorrow: it gets easier every time.</div></div>`)]);
  return out;
}

function totalSecs() {
  return INTRO.reduce((a, b) => a + b) + READY + OUTRO +
    (spec.examples || []).reduce((s, it) => s + 2 * play(it) + GAP + it.pause, 0) +
    spec.items.reduce((s, it) => s + 2 * play(it) + 2 * it.pause, 0);
}

(async () => {
  const browser = await chromium.launch();
  const pg = await browser.newPage({ viewport: { width: W, height: H } });
  for (const [id, html] of slides()) {
    await pg.setContent(html, { waitUntil: 'load' });
    await pg.evaluate(() => document.fonts.ready);
    await pg.screenshot({ path: path.join(work, id + '.png') });
  }
  await browser.close();

  const AF = ['-ar', '44100', '-ac', '1'];
  const V = ['-c:v', 'libx264', '-preset', 'medium', '-tune', 'stillimage', '-crf', '22', '-pix_fmt', 'yuv420p', '-r', String(FPS)];
  const A = ['-c:a', 'aac', '-b:a', '96k', ...AF];
  // A soft two-note chime that tells students it is their turn.
  const chime = path.join(work, 'chime.wav');
  ff(['-f', 'lavfi', '-i', 'sine=f=880:d=0.14', '-f', 'lavfi', '-i', 'sine=f=1320:d=0.22', '-filter_complex',
    '[0]afade=t=out:st=0.08:d=0.06[a];[1]afade=t=out:st=0.08:d=0.14[b];[a][b]concat=n=2:v=0:a=1,volume=0.25', ...AF, chime]);
  const segs = [];
  const still = (img, dur, audioArgs, filt, name) => {
    const f = path.join(work, name + '.mp4');
    ff(['-loop', '1', '-framerate', String(FPS), '-t', dur.toFixed(3), '-i', path.join(work, img + '.png'), ...audioArgs,
      ...(filt ? ['-filter_complex', filt] : []), '-t', dur.toFixed(3), ...V, ...A, '-shortest', f]);
    segs.push(f);
  };
  const silence = (d) => ['-f', 'lavfi', '-t', d.toFixed(3), '-i', `anullsrc=r=44100:cl=mono`];
  const cut = (it, name) => {
    const clip = path.join(work, name + '.wav'), d = clipLen(it);
    ff(['-ss', String(it.start), '-to', String(it.end), '-i', path.join(ROOT, spec.folder, it.src), '-af',
      `afade=t=in:d=0.03,afade=t=out:st=${(d - 0.06).toFixed(3)}:d=0.06,adelay=${LEAD * 1000},apad=pad_dur=${TAIL}`, ...AF, clip]);
    return clip;
  };
  // The timer bar fills the track during the pause; the strip left of the track is put back on top.
  const bar = (P) => `[0:v]split[bg][m];[m]crop=${BAR.x}:${BAR.h}:0:${BAR.y}[left];color=c=${T.accent}:s=${BAR.w}x${BAR.h}:r=${FPS}[fill];` +
    `[bg][fill]overlay=x='${BAR.x - BAR.w}+${BAR.w}*t/${P}':y=${BAR.y}:shortest=1[v1];[v1][left]overlay=0:${BAR.y}`;
  const turn = (P) => ['-i', chime, '-af', `apad=whole_dur=${P}`];
  // Optional spoken intro: spec.voice names the narrator's clips (in voice.dir) for each intro slide.
  const VO = spec.voice;
  const len = (f) => parseFloat(execFileSync('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', f]).toString());
  const norm = {};
  const voice = (id) => {
    if (id === 'chime') return chime;
    if (!norm[id]) {
      norm[id] = path.join(work, `vo-${id}.wav`);
      // Trim the silence at both ends, then normalise (two passes: in one filter chain ffmpeg 6 stalls).
      const trim = path.join(work, `vo-${id}-trim.wav`), sr = 'silenceremove=start_periods=1:start_threshold=-45dB:start_silence=';
      ff(['-i', path.join(ROOT, VO.dir, id + '.mp3'), '-af', `${sr}0.05,areverse,${sr}0.1,areverse`, ...AF, trim]);
      ff(['-i', trim, '-af', 'loudnorm=I=-16:TP=-1.5', ...AF, norm[id]]);
    }
    return norm[id];
  };
  // Joins files and silences ({sil: seconds}) into one wav.
  const seq = (parts, name) => {
    const f = path.join(work, name + '.wav'), ins = [], labels = [];
    parts.forEach((p, k) => {
      if (typeof p === 'object') ins.push('-f', 'lavfi', '-t', String(p.sil), '-i', 'anullsrc=r=44100:cl=mono');
      else ins.push('-i', p);
      labels.push(`[${k}]aresample=44100,aformat=channel_layouts=mono[a${k}]`);
    });
    ff([...ins, '-filter_complex', labels.join(';') + ';' + parts.map((_, k) => `[a${k}]`).join('') + `concat=n=${parts.length}:v=0:a=1`, ...AF, f]);
    return f;
  };
  const spoken = (img, ids, minDur) => {
    const f = seq([{ sil: 0.5 }, ...ids.flatMap((id) => (id === 'chime' ? [{ sil: 0.3 }, chime, { sil: 0.3 }] : [voice(id)])), { sil: 1.2 }], img + '-vo');
    const d = Math.max(minDur, len(f));
    still(img, d, ['-i', f, '-af', `apad=whole_dur=${d}`], null, img);
  };
  if (VO) ['what', 'how', 'tips'].forEach((k, i) => spoken(`i${i}`, VO[k], 5));
  else INTRO.forEach((d, i) => still(`i${i}`, d, silence(d), null, `i${i}`));
  (spec.examples || []).forEach((it, i) => {
    const clip = cut(it, `e${i}`);
    const twice = seq([...(VO ? [{ sil: 0.4 }, ...(VO.examples[i] || []).map(voice), { sil: 0.3 }] : []), clip, { sil: GAP }, clip], `e${i}x2`);
    still(`e${i}a`, len(twice), ['-i', twice], null, `e${i}a`);
    if (VO) {
      const cue = seq([...VO.try.map(voice), { sil: 0.15 }, chime], `e${i}cue`), P = len(cue) + it.pause;
      still(`e${i}b`, P, ['-i', cue, '-af', `apad=whole_dur=${P}`], bar(P), `e${i}b`);
    } else still(`e${i}b`, it.pause, turn(it.pause), bar(it.pause), `e${i}b`);
  });
  if (VO) spoken('ready', VO.ready, READY);
  else still('ready', READY, silence(READY), null, 'ready');
  spec.items.forEach((it, i) => {
    const clip = cut(it, `c${i}`), P = it.pause;
    still(`s${i}a`, play(it), ['-i', clip], null, `s${i}a`);
    still(`s${i}b`, P, turn(P), bar(P), `s${i}b`);
    still(`s${i}c`, play(it), ['-i', clip], null, `s${i}c`);
    still(`s${i}d`, P, turn(P), bar(P), `s${i}d`);
  });
  still('outro', OUTRO, silence(OUTRO), null, 'outro');
  const list = path.join(work, 'list.txt');
  fs.writeFileSync(list, segs.map((f) => `file '${f}'`).join('\n'));
  const out = path.join(ROOT, spec.folder, spec.out);
  ff(['-f', 'concat', '-safe', '0', '-i', list, '-c', 'copy', '-movflags', '+faststart', out]);
  // Poster for the page: the first intro slide.
  ff(['-i', path.join(work, 'i0.png'), '-q:v', '3', out.replace(/\.mp4$/, '-poster.jpg')]);
  console.log(out, totalSecs().toFixed(1) + ' s');
})();
